const bookingUrl = 'https://www.trivalley.fit/booking-calendar/start-here-elite-assessment';
const firstMonday = Date.UTC(2026, 10, 16);
const weekMs = 7 * 86400000;
const stamp = $input.first().json.timestamp;
const weeks = [
  { headline: 'What do your feet do when you squat?', cue: 'Show the cue you use to help the lifter find a stable foot position.', shot_list: 'Film one bodyweight squat from a three-quarter front angle. Show your cue and repeat the rep from the same angle.', caption: 'A rep gives me something to coach. Here’s one thing I look at before adding weight.' },
  { headline: 'Can you find your hip hinge?', cue: 'Show how you teach someone to move their hips back before reaching for a weight.', shot_list: 'Film one side-view hip hinge, your coaching cue, and the next rep from the same position.', caption: 'Here’s how I introduce the hip hinge when I’m coaching someone new.' },
  { headline: 'How steady is your split squat?', cue: 'Demonstrate the stance or support you’d choose for the person in front of you.', shot_list: 'Film the first split squat, the stance or support adjustment, and the next rep.', caption: 'The setup can change how the rep feels. Here’s what I look for first.' },
  { headline: 'What changes during a loaded carry?', cue: 'Show what you watch in the first few steps, then give one cue for the next pass.', shot_list: 'Film the first few steps from the front, your cue, and a second pass from the same angle.', caption: 'The first few steps tell me where to start coaching a carry.' },
  { headline: 'Where do you start after time away?', cue: 'Explain how you pick a first set based on training history and current ability.', shot_list: 'Speak to camera for the hook, demonstrate the first set, and show how you would write the next session.', caption: 'Your first week back should fit where you are today. Here’s how I decide where to start.' },
  { headline: 'What changes when you slow the rep down?', cue: 'Show how a slower rep helps you see what needs attention in one exercise you regularly coach.', shot_list: 'Film a normal rep and a slower rep from the same angle. Explain the one thing you noticed.', caption: 'Watch the same movement at two speeds. I’ll show you what I’m looking for.' }
];
let episode;
if (stamp) {
  const date = new Date(stamp);
  if (!Number.isFinite(date.valueOf())) throw new Error('Schedule timestamp is invalid.');
  const pacific = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Los_Angeles', year: 'numeric', month: '2-digit', day: '2-digit' });
  const parts = Object.fromEntries(pacific.formatToParts(date).map(({ type, value }) => [type, value]));
  const day = Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day));
  const week = Math.floor((day - firstMonday) / weekMs);
  if (week < 0 || week >= weeks.length) return [];
  const monday = new Date(firstMonday + week * weekMs).toISOString().slice(0, 10);
  episode = { episode_id: 'show-me-one-rep-' + monday, ...weeks[week] };
} else {
  episode = {
    episode_id: 'elite-assessment-pilot',
    headline: 'Show me one rep.',
    cue: 'Demonstrate one cue you use during the first squat you assess.',
    shot_list: 'Film a 5–7 second opener to camera. Film an 8–12 second side shot showing a squat, one coaching cue and the next rep. Close on the 60-minute Elite Assessment and $297 price.',
    caption: 'What happens in your first hour with me? We look at how you move, talk through your training history and schedule, and build your first plan. Book your $297 Elite Assessment at the link in bio. — Nick Kaplan, TriValley.fit'
  };
}
if (stamp) episode.caption += ' Want a starting point for your own training? Book your Elite Assessment through the link in bio.';
return [{ json: { ...episode, booking_url: bookingUrl, asset_status: 'awaiting_footage', review_status: 'draft' } }];
